-- Independent vendor credit/refund report integration; no data backfill.
create or replace view public.billing_vendor_statement_events with(security_barrier=true) as
 select b.business_id,b.demo,b.vendor_id,b.id as bill_id,j.id as batch_id,j.date,
 substring(j.number from '([0-9]+)$')::bigint as sequence,j.number,'bill'::text as kind,
 b.data->>'number' as reference,(b.data->>'total')::numeric as charge,0::numeric as credit
 from public.billing_vendor_bills b join public.billing_ledger_batches j on j.id=b.issued_batch
 union all
 select b.business_id,b.demo,b.vendor_id,b.id,j.id,j.date,substring(j.number from '([0-9]+)$')::bigint,j.number,'bill-reversal',
 b.data->>'number',0::numeric,(b.data->>'total')::numeric
 from public.billing_vendor_bills b join public.billing_ledger_batches j on j.reverses_id=b.issued_batch
 union all
 select b.business_id,b.demo,b.vendor_id,b.id,j.id,j.date,substring(j.number from '([0-9]+)$')::bigint,j.number,'payment',
 coalesce(nullif(p.data->>'reference',''),b.data->>'number'),0::numeric,p.amount
 from public.billing_vendor_payments p join public.billing_vendor_bills b on b.id=p.bill_id join public.billing_ledger_batches j on j.id=p.batch_id
 union all
 select b.business_id,b.demo,b.vendor_id,b.id,j.id,j.date,substring(j.number from '([0-9]+)$')::bigint,j.number,'payment-reversal',
 coalesce(nullif(p.data->>'reference',''),b.data->>'number'),p.amount,0::numeric
 from public.billing_vendor_payments p join public.billing_vendor_bills b on b.id=p.bill_id join public.billing_ledger_batches j on j.reverses_id=p.batch_id
 union all
 select c.business_id,c.demo,c.party_id,a.target_id,j.id,a.date,substring(j.number from '([0-9]+)$')::bigint,j.number,
 case when a.kind='allocate' then 'allocation' else 'allocation-release' end,c.number,
 case when a.kind='release' then a.amount else 0::numeric end,case when a.kind='allocate' then a.amount else 0::numeric end
 from public.billing_cash_allocations a join public.billing_cash_events c on c.id=a.cash_id join public.billing_ledger_batches j on j.id=a.batch_id where c.direction='outgoing'
 union all
 select c.business_id,c.demo,c.vendor_id,a.bill_id,j.id,a.date,substring(j.number from '([0-9]+)$')::bigint,j.number,
 case when a.kind='allocate' then 'credit-allocation' else 'credit-release' end,c.number,
 case when a.kind='release' then a.amount else 0::numeric end,case when a.kind='allocate' then a.amount else 0::numeric end
 from public.billing_vendor_credit_allocations a join public.billing_vendor_credits c on c.id=a.credit_id join public.billing_ledger_batches j on j.id=a.batch_id;
revoke all on public.billing_vendor_statement_events from public,anon,authenticated;

create or replace function public.billing_source_reconciliation(business uuid,data_mode boolean,as_of date) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare credit_expected numeric(30,2)=0;credit_actual numeric(30,2)=0;refund_cash numeric(30,2)=0;credit_tax numeric(30,2)=0;advance_in_expected numeric(30,2)=0;advance_out_expected numeric(30,2)=0;advance_in_actual numeric(30,2)=0;advance_out_actual numeric(30,2)=0;cash_new numeric(30,2)=0;ar_allocated numeric(30,2)=0;config public.billing_auto_posting_configs;ledger public.billing_ledger_configs;accounts jsonb;
 ar_expected numeric(30,2)=0;ar_actual numeric(30,2)=0;ap_expected numeric(30,2)=0;ap_actual numeric(30,2)=0;cash_expected numeric(30,2)=0;cash_actual numeric(30,2)=0;tax_expected numeric(30,2)=0;tax_actual numeric(30,2)=0;
 itc_expected numeric(30,2)=0;itc_actual numeric(30,2)=0;itc_account uuid;expense_cash numeric(30,2)=0;unposted_expenses bigint=0;
 cash_vendor numeric(30,2)=0;unposted bigint=0;legacy bigint=0;foreign_docs bigint=0;ap_account uuid;row_count bigint;result jsonb;source_rows bigint;
begin
 if auth.uid() is null or not public.billing_can_access(business) then raise exception using errcode='42501',message='Source reconciliation unavailable in this business';end if;
 if data_mode is null or as_of is null or not isfinite(as_of) then raise exception 'Choose a valid reconciliation date';end if;
 select * into ledger from public.billing_ledger_configs where business_id=business and demo=data_mode;
 select * into config from public.billing_auto_posting_configs where business_id=business and demo=data_mode;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'type',type) order by code),'[]'::jsonb) into accounts from public.billing_ledger_accounts where business_id=business and demo=data_mode;
 if config.business_id is null then return jsonb_build_object('businessId',business,'demo',data_mode,'configured',false,'ledgerConfigured',ledger.business_id is not null,'canManage',public.billing_is_owner(business),'accounts',accounts,'currency',ledger.currency,'ledgerStart',ledger.start_date,'asOf',as_of,'reviewStatus','unreviewed');end if;
 with documents as(
  select i.*,case when i.type='credit-note' then -1 else 1 end as sign,c.date as cancelled_on from public.billing_issued_documents i left join public.billing_document_cancellations c on c.document_id=i.document_id
  where i.business_id=business and i.demo=data_mode and i.date>=config.cutover_date and i.date<=as_of and i.snapshot->>'currency'=config.currency and i.type in ('invoice','gst-invoice','commercial-invoice','credit-note','debit-note')
 ) select coalesce(sum((snapshot->'totals'->>'total')::numeric*sign) filter(where cancelled_on is null or cancelled_on>as_of),0),coalesce(sum(((snapshot->'totals'->>'tax')::numeric+(snapshot->'totals'->>'cess')::numeric)*sign) filter(where cancelled_on is null or cancelled_on>as_of),0),count(*) into ar_expected,tax_expected,source_rows from documents;
 select ar_expected-coalesce(sum(case when p.kind='receipt' then p.amount else -p.amount end),0),coalesce(sum(case when p.kind='receipt' then p.amount else -p.amount end),0) into ar_expected,cash_expected
 from public.billing_payment_events p join public.billing_issued_documents i on i.document_id=p.document_id
 where p.business_id=business and p.demo=data_mode and p.transaction_date between config.cutover_date and as_of and p.currency=config.currency and i.date>=config.cutover_date;
 select coalesce(sum(e.charge-e.credit),0) into ap_expected from public.billing_vendor_statement_events e where e.business_id=business and e.demo=data_mode and e.date<=as_of;
 select coalesce(sum(p.amount) filter(where p.date<=as_of),0)-coalesce(sum(p.amount) filter(where r.date<=as_of),0) into cash_vendor from public.billing_vendor_payments p left join public.billing_ledger_batches r on r.reverses_id=p.batch_id where p.business_id=business and p.demo=data_mode and p.account_id=config.cash_account;
 cash_expected=cash_expected-cash_vendor;
 select coalesce(sum(p.gross_amount) filter(where p.cash_account=config.cash_account),0),coalesce(sum(p.input_tax),0) into expense_cash,itc_expected from public.billing_posted_expenses p left join public.billing_expense_reversals r on r.expense_id=p.expense_id where p.business_id=business and p.demo=data_mode and p.date<=as_of and (r.id is null or r.date>as_of);
 cash_expected=cash_expected-expense_cash;
 select itc_expected+coalesce(sum((b.data->>'taxAmount')::numeric),0) into itc_expected from public.billing_vendor_bills b where b.business_id=business and b.demo=data_mode and b.status='issued' and (b.data->>'date')::date<=as_of and not exists(select 1 from public.billing_ledger_batches r where r.reverses_id=b.issued_batch and r.date<=as_of);
 select id into itc_account from public.billing_ledger_accounts where business_id=business and demo=data_mode and code='1300' and type='asset';
 select coalesce(sum(e.debit-e.credit),0) into itc_actual from public.billing_ledger_entries e join public.billing_ledger_batches b on b.id=e.batch_id where e.business_id=business and e.demo=data_mode and e.account_id=itc_account and b.date<=as_of;
 select count(*) into unposted_expenses from public.billing_records r where r.business_id=business and r.demo=data_mode and r.collection='expenses' and not r.archived and r.data->>'date'<=as_of::text and not exists(select 1 from public.billing_posted_expenses p where p.expense_id=r.id);

 select id into ap_account from public.billing_ledger_accounts where business_id=business and demo=data_mode and code='2000' and type='liability';
 select coalesce(sum(c.amount*case when c.direction='incoming' then 1 else -1 end*case when c.kind='cash' then 1 else -1 end),0) into cash_new from public.billing_cash_events c where c.business_id=business and c.demo=data_mode and c.date<=as_of;
 cash_expected=cash_expected+cash_new;
 select coalesce(sum(f.amount*case when f.direction='incoming' then 1 else -1 end*case when f.kind='refund' then 1 else -1 end),0) into refund_cash from public.billing_refund_events f where f.business_id=business and f.demo=data_mode and f.date<=as_of;
 cash_expected=cash_expected+refund_cash;
 select coalesce(sum(c.tax_amount),0) into credit_tax from public.billing_vendor_credits c where c.business_id=business and c.demo=data_mode and c.date<=as_of and not exists(select 1 from public.billing_vendor_credit_reversals r where r.credit_id=c.id and r.date<=as_of);
 itc_expected=itc_expected-credit_tax;
 select coalesce(sum(coalesce((select sum(m.delta) from public.billing_vendor_credit_movements(c.id)m where m.date<=as_of),0)),0) into credit_expected from public.billing_vendor_credits c where c.business_id=business and c.demo=data_mode;
 select coalesce(sum(e.debit-e.credit),0) into credit_actual from public.billing_ledger_entries e join public.billing_ledger_accounts a on a.id=e.account_id join public.billing_ledger_batches b on b.id=e.batch_id where e.business_id=business and e.demo=data_mode and a.code='1450' and b.date<=as_of;

 select coalesce(sum(a.amount*case when a.kind='allocate' then 1 else -1 end),0) into ar_allocated from public.billing_cash_allocations a join public.billing_cash_events c on c.id=a.cash_id where a.business_id=business and a.demo=data_mode and a.date<=as_of and c.direction='incoming';
 ar_expected=ar_expected-ar_allocated;
 with funds as(select c.id,c.direction,coalesce((select sum(m.delta) from public.billing_cash_movements(c.id)m where m.date<=as_of),0) amount from public.billing_cash_events c where c.business_id=business and c.demo=data_mode and c.kind='cash')
 select coalesce(sum(amount) filter(where direction='incoming'),0),coalesce(sum(amount) filter(where direction='outgoing'),0) into advance_in_expected,advance_out_expected from funds;
 select coalesce(sum(e.credit-e.debit) filter(where a.code='2200'),0),coalesce(sum(e.debit-e.credit) filter(where a.code='1400'),0) into advance_in_actual,advance_out_actual from public.billing_ledger_entries e join public.billing_ledger_accounts a on a.id=e.account_id join public.billing_ledger_batches b on b.id=e.batch_id where e.business_id=business and e.demo=data_mode and b.date<=as_of;
 select coalesce(sum(e.debit-e.credit) filter(where e.account_id=config.receivable_account),0),coalesce(sum(e.credit-e.debit) filter(where e.account_id=ap_account),0),coalesce(sum(e.debit-e.credit) filter(where e.account_id=config.cash_account),0),coalesce(sum(e.credit-e.debit) filter(where e.account_id=config.tax_account),0) into ar_actual,ap_actual,cash_actual,tax_actual
 from public.billing_ledger_entries e join public.billing_ledger_batches b on b.id=e.batch_id where e.business_id=business and e.demo=data_mode and b.date<=as_of;
 select count(*) filter(where i.document_id is null),count(*) filter(where i.document_id is not null and not exists(select 1 from public.billing_source_postings p where p.source_id=r.id and p.kind='document.issue')),count(*) filter(where r.data->>'currency'<>config.currency)
 into legacy,unposted,foreign_docs from public.billing_records r left join public.billing_issued_documents i on i.document_id=r.id
 where r.business_id=business and r.demo=data_mode and r.collection='documents' and not r.archived and r.data->>'type' in ('invoice','gst-invoice','commercial-invoice','credit-note','debit-note') and (r.data->>'status' in ('sent','paid') or r.data->>'status'='cancelled' and i.document_id is not null) and (r.data->>'date')::date<=as_of;
 return jsonb_build_object('businessId',business,'demo',data_mode,'configured',true,'ledgerConfigured',true,'canManage',public.billing_is_owner(business),'config',to_jsonb(config),'currency',config.currency,'asOf',as_of,'accounts',accounts,'controls',jsonb_build_array(
 jsonb_build_object('code','AR','name','Accounts receivable','expected',ar_expected::text,'ledger',ar_actual::text,'difference',(ar_actual-ar_expected)::text),
 jsonb_build_object('code','AP','name','Accounts payable','expected',ap_expected::text,'ledger',ap_actual::text,'difference',(ap_actual-ap_expected)::text),
 jsonb_build_object('code','CASH','name','Cash / bank','expected',cash_expected::text,'ledger',cash_actual::text,'difference',(cash_actual-cash_expected)::text),
 jsonb_build_object('code','TAX','name','Output tax payable','expected',tax_expected::text,'ledger',tax_actual::text,'difference',(tax_actual-tax_expected)::text),jsonb_build_object('code','ITC','name','Reviewed input tax receivable','expected',itc_expected::text,'ledger',itc_actual::text,'difference',(itc_actual-itc_expected)::text),
 jsonb_build_object('code','CUSTOMER_ADVANCE','name','Unapplied customer cash','expected',advance_in_expected::text,'ledger',advance_in_actual::text,'difference',(advance_in_actual-advance_in_expected)::text),
 jsonb_build_object('code','VENDOR_ADVANCE','name','Unapplied vendor disbursements','expected',advance_out_expected::text,'ledger',advance_out_actual::text,'difference',(advance_out_actual-advance_out_expected)::text),jsonb_build_object('code','VENDOR_CREDIT','name','Unapplied supplier credits','expected',credit_expected::text,'ledger',credit_actual::text,'difference',(credit_actual-credit_expected)::text)),
 'unpostedExpenses',unposted_expenses,'unpostedManagedDocuments',unposted,'legacyDocumentsNeedingOpeningReview',legacy,'foreignDocumentsNeedingFxReview',foreign_docs,'managedDocumentsThroughDate',source_rows,'arithmeticAgrees',ar_actual=ar_expected and ap_actual=ap_expected and cash_actual=cash_expected and tax_actual=tax_expected and itc_actual=itc_expected and advance_in_actual=advance_in_expected and advance_out_actual=advance_out_expected and credit_actual=credit_expected and unposted_expenses=0 and unposted=0 and legacy=0 and foreign_docs=0,'reviewStatus','unreviewed',
 'limitations',jsonb_build_array('Mechanical control-account comparison only; personal review decisions are recorded separately and this result does not assert sign-off. Supplier credit tax amounts are user-reviewed corrections, not completed GST filings.','Expected AR/output tax uses frozen managed documents and dated receipt/cancellation events after cutover. No paid flag becomes cash.','Expected AP uses explicit Folio vendor bills/payments/reversals. Cash allocations/releases are included once; unapplied advances are independent controls. Supplier credit allocations/releases reduce AP; supplier credit issues/refunds stay separate from bill aging. Manual journals are not invented.','Expected cash also includes explicit paid expense snapshots/reversals; reviewed input tax includes expense and vendor bill snapshots. Unposted expenses require opening/source review.','Manual/opening control-account entries can cause differences and need reviewed mappings. FX, inventory and additional expense sources remain separate work.'));
end$$;

create or replace function public.billing_cash_read(business uuid,data_mode boolean,as_of date,cash_id uuid default null,target_id uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare refund_rows jsonb='[]';config public.billing_cash_configs;ledger public.billing_ledger_configs;selected public.billing_cash_events;rows jsonb;allocations jsonb='[]';parties jsonb;accounts jsonb;targets jsonb='[]';target_count bigint=0;cash_count bigint;available numeric(30,2);in_advance numeric(30,2);out_advance numeric(30,2);incoming numeric(30,2);outgoing numeric(30,2);detail jsonb=null;
begin
 if auth.uid() is null or not public.billing_can_access(business) then raise exception using errcode='42501',message='Cash workspace unavailable in this business';end if;
 if data_mode is null or as_of is null or not isfinite(as_of) then raise exception 'Choose a cash review date and data mode';end if;
 select * into config from public.billing_cash_configs where business_id=business and demo=data_mode;
 select * into ledger from public.billing_ledger_configs where business_id=business and demo=data_mode;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'type',type) order by code),'[]'::jsonb) into accounts from public.billing_ledger_accounts where business_id=business and demo=data_mode;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'kind',collection,'name',data->>'name') order by data->>'name',id),'[]'::jsonb) into parties from(select id,collection,data from public.billing_records where business_id=business and demo=data_mode and collection in ('clients','vendors') and not archived order by data->>'name',id limit 500)p;
 select count(*) into cash_count from public.billing_cash_events where business_id=business and demo=data_mode and kind='cash';
 with funds as(select c.direction,coalesce((select sum(m.delta) from public.billing_cash_movements(c.id)m where m.date<=as_of),0) amount from public.billing_cash_events c where c.business_id=business and c.demo=data_mode and c.kind='cash') select coalesce(sum(amount) filter(where direction='incoming'),0),coalesce(sum(amount) filter(where direction='outgoing'),0) into in_advance,out_advance from funds;
 select coalesce(sum(c.amount*case when c.kind='cash' then 1 else -1 end) filter(where c.direction='incoming'),0),coalesce(sum(c.amount*case when c.kind='cash' then 1 else -1 end) filter(where c.direction='outgoing'),0) into incoming,outgoing from public.billing_cash_events c where c.business_id=business and c.demo=data_mode and c.date<=as_of;
 select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('amount',c.amount::text,'available',coalesce((select sum(m.delta) from public.billing_cash_movements(c.id)m where m.date<=as_of),0)::numeric(30,2)::text,'reversalDate',(select date from public.billing_cash_events r where r.reverses_id=c.id)) order by c.created_at desc,c.id desc),'[]'::jsonb) into rows from(select * from public.billing_cash_events where business_id=business and demo=data_mode and kind='cash' order by created_at desc,id desc limit 200)c;
 if cash_id is not null then
  select * into selected from public.billing_cash_events c where c.id=cash_id and c.business_id=business and c.demo=data_mode and c.kind='cash';
  if selected.id is null then raise exception using errcode='P0002',message='Cash event unavailable in this business and data mode';end if;
  if (select count(*) from public.billing_cash_allocations a where a.cash_id=selected.id)>1000 then raise exception 'Cash detail exceeds 1,000 allocation movements; no partial history is shown';end if;
  if (select count(*) from public.billing_refund_events f where f.source_kind='cash' and f.source_id=selected.id)>1000 then raise exception 'Cash detail exceeds 1,000 refund movements; no partial history is shown';end if;
  select coalesce(jsonb_agg(to_jsonb(f)||jsonb_build_object('amount',f.amount::text) order by f.date,f.created_at,f.id),'[]'::jsonb) into refund_rows from public.billing_refund_events f where f.source_kind='cash' and f.source_id=selected.id;
  select coalesce(sum(m.delta),0) into available from public.billing_cash_movements(selected.id)m where m.date<=as_of;
  select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('amount',a.amount::text,'remainingReleasable',case when a.kind='allocate' then a.amount-coalesce((select sum(r.amount) from public.billing_cash_allocations r where r.releases_id=a.id),0) else 0 end::numeric(30,2)::text) order by a.date,a.created_at,a.id),'[]'::jsonb) into allocations from public.billing_cash_allocations a where a.cash_id=selected.id;
  detail=to_jsonb(selected)||jsonb_build_object('amount',selected.amount::text,'available',available::text,'reversalDate',(select date from public.billing_cash_events r where r.reverses_id=selected.id));
  if selected.direction='incoming' then
   select count(*) into target_count from public.billing_records r where r.business_id=business and r.demo=data_mode and r.collection='documents' and not r.archived and r.data->>'clientId'=selected.party_id::text and r.data->>'currency'=selected.currency and r.data->>'type' in ('invoice','gst-invoice','commercial-invoice') and exists(select 1 from public.billing_source_postings where source_id=r.id and kind='document.issue') and not exists(select 1 from public.billing_document_cancellations where document_id=r.id);
   select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'version',r.version,'number',r.data->>'number','date',r.data->>'date','dueDate',r.data->>'dueDate','balance',coalesce((select sum(m.delta) from public.billing_settlement_movements(r.id,'incoming')m where m.date<=as_of),0)::numeric(30,2)::text) order by r.data->>'date',r.id),'[]'::jsonb) into targets from(select * from public.billing_records r where r.business_id=business and r.demo=data_mode and r.collection='documents' and not r.archived and r.data->>'clientId'=selected.party_id::text and r.data->>'currency'=selected.currency and r.data->>'type' in ('invoice','gst-invoice','commercial-invoice') and exists(select 1 from public.billing_source_postings where source_id=r.id and kind='document.issue') and not exists(select 1 from public.billing_document_cancellations where document_id=r.id) and (target_id is null or r.id=target_id) order by r.data->>'date',r.id limit 500)r;
  else
   select count(*) into target_count from public.billing_vendor_bills b where b.business_id=business and b.demo=data_mode and b.vendor_id=selected.party_id and b.status='issued' and not exists(select 1 from public.billing_ledger_batches where reverses_id=b.issued_batch);
   select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'version',b.version,'number',b.data->>'number','date',b.data->>'date','dueDate',b.data->>'dueDate','balance',coalesce((select sum(m.delta) from public.billing_settlement_movements(b.id,'outgoing')m where m.date<=as_of),0)::numeric(30,2)::text) order by b.data->>'date',b.id),'[]'::jsonb) into targets from(select * from public.billing_vendor_bills b where b.business_id=business and b.demo=data_mode and b.vendor_id=selected.party_id and b.status='issued' and not exists(select 1 from public.billing_ledger_batches where reverses_id=b.issued_batch) and (target_id is null or b.id=target_id) order by b.data->>'date',b.id limit 500)b;
  end if;
  if target_id is not null and jsonb_array_length(targets)=0 then raise exception using errcode='P0002',message='Allocation target unavailable for this cash party and data mode';end if;
 elsif target_id is not null then raise exception 'Choose cash before an exact allocation target';end if;
 return jsonb_build_object('businessId',business,'demo',data_mode,'asOf',as_of,'configured',config.business_id is not null,'ledgerConfigured',ledger.business_id is not null,'currency',ledger.currency,'config',case when config.business_id is null then null else to_jsonb(config) end,'canWrite',public.billing_can_access(business,true),'canManage',public.billing_is_owner(business),'accounts',accounts,'parties',parties,'partiesTruncated',(select count(*)>500 from public.billing_records where business_id=business and demo=data_mode and collection in ('clients','vendors') and not archived),'cashEvents',rows,'cashCount',cash_count,'cashTruncated',cash_count>200,'cash',detail,'allocations',allocations,'refunds',refund_rows,'targets',targets,'targetCount',target_count,'targetsTruncated',target_id is null and target_count>500,'exactTarget',target_id,'totals',jsonb_build_object('incoming',incoming::text,'outgoing',outgoing::text,'customerAdvance',in_advance::text,'vendorAdvance',out_advance::text),'fundsMovedByFolio',false);
end$$;

notify pgrst,'reload schema';

create function public.billing_vendor_credit_read(business uuid,data_mode boolean,as_of date,credit_id uuid default null,bill_id uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare config public.billing_cash_configs;selected public.billing_vendor_credits;source public.billing_vendor_bills;credits jsonb;details jsonb=null;allocations jsonb='[]';refunds jsonb='[]';targets jsonb='[]';bills jsonb;accounts jsonb;credit_count bigint;bill_count bigint;target_count bigint=0;unapplied numeric(30,2);total numeric(30,2);available numeric(30,2);
begin
 if auth.uid() is null or not public.billing_can_access(business) then raise exception using errcode='42501',message='Vendor credits unavailable in this business';end if;
 if data_mode is null or as_of is null or not isfinite(as_of) then raise exception 'Choose a valid credit review date and data mode';end if;
 select * into config from public.billing_cash_configs where business_id=business and demo=data_mode;
 select count(*) into credit_count from public.billing_vendor_credits where business_id=business and demo=data_mode;
 select count(*) into bill_count from public.billing_vendor_bills b where b.business_id=business and b.demo=data_mode and b.status='issued' and not exists(select 1 from public.billing_ledger_batches where reverses_id=b.issued_batch);
 select coalesce(sum(c.amount) filter(where c.date<=as_of and not exists(select 1 from public.billing_vendor_credit_reversals r where r.credit_id=c.id and r.date<=as_of)),0),coalesce(sum(coalesce((select sum(m.delta) from public.billing_vendor_credit_movements(c.id)m where m.date<=as_of),0)),0) into total,unapplied from public.billing_vendor_credits c where c.business_id=business and c.demo=data_mode;
 select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('amount',c.amount::text,'subtotal',c.subtotal::text,'tax_amount',c.tax_amount::text,'available',coalesce((select sum(m.delta) from public.billing_vendor_credit_movements(c.id)m where m.date<=as_of),0)::numeric(30,2)::text,'reversalDate',(select date from public.billing_vendor_credit_reversals r where r.credit_id=c.id)) order by c.created_at desc,c.id desc),'[]'::jsonb) into credits from(select * from public.billing_vendor_credits where business_id=business and demo=data_mode order by created_at desc,id desc limit 200)c;
 select coalesce(jsonb_agg(to_jsonb(b) order by b.created_at desc,b.id desc),'[]'::jsonb) into bills from(select * from public.billing_vendor_bills b where b.business_id=business and b.demo=data_mode and b.status='issued' and not exists(select 1 from public.billing_ledger_batches where reverses_id=b.issued_batch) order by b.created_at desc,b.id desc limit 200)b;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'type',type)),'[]'::jsonb) into accounts from public.billing_ledger_accounts where business_id=business and demo=data_mode and type='asset' and code='1450';
 if bill_id is not null then
  select * into source from public.billing_vendor_bills b where b.id=bill_id and b.business_id=business and b.demo=data_mode and b.status='issued' and not exists(select 1 from public.billing_ledger_batches where reverses_id=b.issued_batch);
  if source.id is null then raise exception using errcode='P0002',message='Active source/target bill unavailable in this business and data mode';end if;
 end if;
 if credit_id is not null then
  select * into selected from public.billing_vendor_credits c where c.id=credit_id and c.business_id=business and c.demo=data_mode;
  if selected.id is null then raise exception using errcode='P0002',message='Vendor credit unavailable in this business and data mode';end if;
  if (select count(*) from public.billing_vendor_credit_allocations where public.billing_vendor_credit_allocations.credit_id=selected.id)>1000 or (select count(*) from public.billing_refund_events where source_kind='vendor-credit' and source_id=selected.id)>1000 then raise exception 'Credit detail exceeds 1,000 allocation/refund movements; no partial history is shown';end if;
  select coalesce(sum(m.delta),0) into available from public.billing_vendor_credit_movements(selected.id)m where m.date<=as_of;
  details=to_jsonb(selected)||jsonb_build_object('amount',selected.amount::text,'subtotal',selected.subtotal::text,'tax_amount',selected.tax_amount::text,'available',available::text,'reversalDate',(select date from public.billing_vendor_credit_reversals where public.billing_vendor_credit_reversals.credit_id=selected.id));
  select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('amount',a.amount::text,'remainingReleasable',case when a.kind='allocate' then a.amount-coalesce((select sum(r.amount) from public.billing_vendor_credit_allocations r where r.releases_id=a.id),0) else 0 end::numeric(30,2)::text) order by a.date,a.created_at,a.id),'[]'::jsonb) into allocations from public.billing_vendor_credit_allocations a where a.credit_id=selected.id;
  select coalesce(jsonb_agg(to_jsonb(f)||jsonb_build_object('amount',f.amount::text) order by f.date,f.created_at,f.id),'[]'::jsonb) into refunds from public.billing_refund_events f where f.source_kind='vendor-credit' and f.source_id=selected.id;
  select count(*) into target_count from public.billing_vendor_bills b where b.business_id=business and b.demo=data_mode and b.vendor_id=selected.vendor_id and b.status='issued' and not exists(select 1 from public.billing_ledger_batches where reverses_id=b.issued_batch);
  if source.id is not null and source.vendor_id<>selected.vendor_id then raise exception using errcode='P0002',message='Bill is not for this credit vendor';end if;
  select coalesce(jsonb_agg(to_jsonb(b)||jsonb_build_object('balance',coalesce((select sum(m.delta) from public.billing_settlement_movements(b.id,'outgoing')m where m.date<=as_of),0)::numeric(30,2)::text) order by b.data->>'date',b.id),'[]'::jsonb) into targets from(select * from public.billing_vendor_bills b where b.business_id=business and b.demo=data_mode and b.vendor_id=selected.vendor_id and b.status='issued' and not exists(select 1 from public.billing_ledger_batches where reverses_id=b.issued_batch) and (bill_id is null or b.id=bill_id) order by b.data->>'date',b.id limit 500)b;
 end if;
 return jsonb_build_object('businessId',business,'demo',data_mode,'asOf',as_of,'configured',config.business_id is not null,'currency',config.currency,'canWrite',public.billing_can_access(business,true),'credits',credits,'creditCount',credit_count,'creditsTruncated',credit_count>200,'bills',bills,'billCount',bill_count,'billsTruncated',bill_count>200,'sourceBill',case when source.id is null then null else to_jsonb(source) end,'credit',details,'allocations',allocations,'refunds',refunds,'targets',targets,'targetCount',target_count,'targetsTruncated',bill_id is null and target_count>500,'accounts',accounts,'totalCredits',total::text,'unapplied',unapplied::text,'fundsMovedByFolio',false);
end$$;
revoke all on function public.billing_vendor_credit_read(uuid,boolean,date,uuid,uuid) from public,anon,authenticated;
grant execute on function public.billing_vendor_credit_read(uuid,boolean,date,uuid,uuid) to authenticated;
notify pgrst,'reload schema';

create or replace function public.billing_vendor_bills_read(business uuid,data_mode boolean,as_of date) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare config public.billing_ledger_configs;rows jsonb;vendors jsonb;accounts jsonb;total numeric;overdue numeric;bill_count integer;
begin
 if auth.uid() is null or not public.billing_can_access(business) then raise exception using errcode='42501',message='Vendor bills unavailable in this business';end if;
 if data_mode is null or as_of is null or not isfinite(as_of) then raise exception 'Choose a valid payables date';end if;
 select * into config from public.billing_ledger_configs where business_id=business and demo=data_mode;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',data->>'name') order by data->>'name',id),'[]'::jsonb) into vendors from (select id,data from public.billing_records where business_id=business and demo=data_mode and collection='vendors' and not archived order by data->>'name',id limit 500)v;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'type',type) order by code),'[]'::jsonb) into accounts from public.billing_ledger_accounts where business_id=business and demo=data_mode and (type='expense' or (type='asset' and code not in ('1000','1100','1300','1400','1450')));
 select count(*) into bill_count from public.billing_vendor_bills where business_id=business and demo=data_mode;
 with balances as(select e.bill_id,sum(e.charge-e.credit) balance from public.billing_vendor_statement_events e where e.business_id=business and e.demo=data_mode and e.date<=as_of group by e.bill_id)
 select coalesce(sum(x.balance),0),coalesce(sum(x.balance) filter(where (b.data->>'dueDate')::date<as_of),0) into total,overdue from balances x join public.billing_vendor_bills b on b.id=x.bill_id;
 select coalesce(jsonb_agg(to_jsonb(b)||jsonb_build_object('balance',coalesce((select sum(e.charge-e.credit) from public.billing_vendor_statement_events e where e.bill_id=b.id and e.date<=as_of),0)::numeric(30,2)::text,'payments',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('amount',p.amount::text,'number',j.number,'reversalDate',r.date,'reversalId',r.id) order by p.date,p.created_at,p.id) from public.billing_vendor_payments p join public.billing_ledger_batches j on j.id=p.batch_id left join public.billing_ledger_batches r on r.reverses_id=p.batch_id where p.bill_id=b.id),'[]'::jsonb),'allocations',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'cashId',a.cash_id,'kind',a.kind,'date',a.date,'amount',a.amount::text,'cashNumber',c.number) order by a.date,a.created_at,a.id) from public.billing_cash_allocations a join public.billing_cash_events c on c.id=a.cash_id where a.target_id=b.id and c.direction='outgoing'),'[]'::jsonb),'creditAllocations',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'creditId',a.credit_id,'kind',a.kind,'date',a.date,'amount',a.amount::text,'creditNumber',c.number) order by a.date,a.created_at,a.id) from public.billing_vendor_credit_allocations a join public.billing_vendor_credits c on c.id=a.credit_id where a.bill_id=b.id),'[]'::jsonb),'reversalDate',(select r.date from public.billing_ledger_batches r where r.reverses_id=b.issued_batch)) order by created_at desc,id desc),'[]'::jsonb) into rows from (select * from public.billing_vendor_bills where business_id=business and demo=data_mode order by created_at desc,id desc limit 500)b;
 return jsonb_build_object('configured',config.business_id is not null,'currency',config.currency,'canWrite',public.billing_can_access(business,true),'asOf',as_of,'bills',rows,'vendors',vendors,'accounts',accounts,'totalDue',total::text,'overdue',overdue::text,'billCount',bill_count,'billsTruncated',bill_count>500,'vendorsTruncated',(select count(*)>500 from public.billing_records where business_id=business and demo=data_mode and collection='vendors' and not archived),'paymentAccounts',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'code',code)),'[]'::jsonb) from public.billing_ledger_accounts where business_id=business and demo=data_mode and code='1000' and type='asset'),'settlementsAvailable',true);
end$$;

create or replace function public.billing_vendor_bill_detail(business uuid,data_mode boolean,bill_id uuid,as_of date) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare bill public.billing_vendor_bills;config public.billing_ledger_configs;bill_json jsonb;vendors jsonb;accounts jsonb;payments jsonb;total numeric;overdue numeric;bill_count bigint;balance numeric;reversed date;
begin
 if auth.uid() is null or not public.billing_can_access(business) then raise exception using errcode='42501',message='Vendor bill unavailable in this business';end if;
 if data_mode is null or bill_id is null or as_of is null or not isfinite(as_of) then raise exception 'Choose a valid bill and payables date';end if;
 select * into bill from public.billing_vendor_bills b where b.id=bill_id and b.business_id=business and b.demo=data_mode;
 if bill.id is null then raise exception using errcode='P0002',message='Vendor bill unavailable in this business and data mode';end if;
 select * into config from public.billing_ledger_configs where business_id=business and demo=data_mode;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',data->>'name') order by data->>'name',id),'[]'::jsonb) into vendors from (
  select id,data from public.billing_records where business_id=business and demo=data_mode and collection='vendors' and not archived and id=bill.vendor_id
  union all select id,data from (select id,data from public.billing_records where business_id=business and demo=data_mode and collection='vendors' and not archived and id<>bill.vendor_id order by data->>'name',id limit 500)other_vendors
 )v;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'type',type) order by code),'[]'::jsonb) into accounts from public.billing_ledger_accounts where business_id=business and demo=data_mode and (type='expense' or (type='asset' and code not in ('1000','1100','1300','1400','1450')));
 select count(*) into bill_count from public.billing_vendor_bills b where b.business_id=business and b.demo=data_mode;
 with balances as(
  select e.bill_id,sum(e.charge-e.credit) as balance from public.billing_vendor_statement_events e where e.business_id=business and e.demo=data_mode and e.date<=as_of group by e.bill_id
 )select coalesce(sum(x.balance),0),coalesce(sum(x.balance) filter(where (b.data->>'dueDate')::date<as_of),0) into total,overdue from balances x join public.billing_vendor_bills b on b.id=x.bill_id;
 select coalesce(sum(e.charge-e.credit),0) into balance from public.billing_vendor_statement_events e where e.business_id=business and e.demo=data_mode and e.bill_id=bill.id and e.date<=as_of;
 select date into reversed from public.billing_ledger_batches r where r.reverses_id=bill.issued_batch;
 select coalesce(jsonb_agg(to_jsonb(p)||jsonb_build_object('amount',p.amount::text,'number',j.number,'reversalDate',r.date,'reversalId',r.id) order by p.date,p.created_at,p.id),'[]'::jsonb) into payments from public.billing_vendor_payments p join public.billing_ledger_batches j on j.id=p.batch_id left join public.billing_ledger_batches r on r.reverses_id=p.batch_id where p.bill_id=bill.id;
 bill_json=to_jsonb(bill)||jsonb_build_object('balance',balance::text,'reversalDate',reversed,'payments',payments,'creditAllocations',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'creditId',a.credit_id,'kind',a.kind,'date',a.date,'amount',a.amount::text,'creditNumber',c.number) order by a.date,a.created_at,a.id) from public.billing_vendor_credit_allocations a join public.billing_vendor_credits c on c.id=a.credit_id where a.bill_id=bill.id),'[]'::jsonb),'allocations',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'cashId',a.cash_id,'kind',a.kind,'date',a.date,'amount',a.amount::text,'cashNumber',c.number) order by a.date,a.created_at,a.id) from public.billing_cash_allocations a join public.billing_cash_events c on c.id=a.cash_id where a.target_id=bill.id and c.direction='outgoing'),'[]'::jsonb));
 return jsonb_build_object('configured',config.business_id is not null,'currency',config.currency,'canWrite',public.billing_can_access(business,true),'asOf',as_of,'bills',jsonb_build_array(bill_json),'vendors',vendors,'accounts',accounts,'totalDue',total::text,'overdue',overdue::text,'billCount',bill_count,'billsTruncated',false,'detailOnly',true,'vendorsTruncated',(select count(*)>500 from public.billing_records where business_id=business and demo=data_mode and collection='vendors' and not archived),'paymentAccounts',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'code',code)),'[]'::jsonb) from public.billing_ledger_accounts where business_id=business and demo=data_mode and code='1000' and type='asset'),'settlementsAvailable',true);
end$$;

notify pgrst,'reload schema';
